async function reload(force=false){try{const fresh=await api('/api/host');if(pending&&!force)return;if(!data){data=fresh;sample=Boolean(fresh.sampleLoaded);$('#sampleButton').classList.toggle('active',sample);selected=activePeople()[0].id;previewPhase=data.plan.phases[0].id;render();fit();if(new URLSearchParams(location.search).get('view')==='students')studentVersionsModal();else if(typeof tutorialBoot==='function')tutorialBoot();return}const changed=fresh.planRev!==lastPlanRev;const roster=JSON.stringify(data.people)!==JSON.stringify(fresh.people);data=fresh;sample=Boolean(fresh.sampleLoaded);$('#sampleButton').classList.toggle('active',sample);if(changed||roster||force){lastPlanRev=data.planRev;render(!(document.activeElement?.closest('.inspector-body')))}$('#saveState').textContent=pending?'Saving…':'Saved locally';$('#connectionLabel').textContent='Local session · '+activePeople().length+' places';}catch(e){$('#saveState').textContent='Reconnecting…';$('#saveState').classList.add('connection-error');if(!data)showModal('<h2>Open the host link</h2><p>Use the link opened by “Open Activity Canvas.command”.</p>')}}
